-- Chạy cùng migration 94 trong DO tự hoàn tác; chỉ xuất tên kiểm tra, không xuất dữ liệu thật.
do $checks$
declare owner_id bigint; owner_uid uuid; kt bigint; kt_uid uuid:=gen_random_uuid(); nv bigint; nv_uid uuid:=gen_random_uuid(); emp bigint; doc bigint;
  tid bigint; source_task bigint; rid bigint; p jsonb; s jsonb; preview jsonb; out jsonb; before_ int; blocked boolean; cases text[]:='{}';
  br bigint; q1 bigint; q2 bigint; t0 timestamptz; inv bigint; rt bigint; bt bigint; sr bigint; tr bigint;
begin
  select id,auth_user_id into owner_id,owner_uid from public.accounts where system_role='chu' and locked=0 and auth_user_id is not null limit 1;
  if owner_id is null then raise exception 'Thiếu Chủ để chạy kiểm tra tự hoàn tác.'; end if;
  perform set_config('request.jwt.claim.sub',owner_uid::text,true);
  insert into public.employees(code,name,rank) values('CV93_'||substr(gen_random_uuid()::text,1,8),'Nhân viên kiểm thử','1') returning id into emp;
  update public.accounts set display_name='Tài khoản kiểm thử',system_role='nv',auth_user_id=nv_uid where employee_id=emp returning id into nv;
  if nv is null then insert into public.accounts(employee_id,display_name,system_role,auth_user_id) values(emp,'Tài khoản kiểm thử','nv',nv_uid) returning id into nv; end if;
  insert into public.accounts(login_name,display_name,system_role,auth_user_id) values('cv93_'||substr(gen_random_uuid()::text,1,8),'Kế toán kiểm thử','ke_toan',kt_uid) returning id into kt;
  if not public.app__cv_can_as(kt,'ke_toan') or not public.app__cv_can_as(kt,'nhan_viec') or public.app__cv_can_as(kt,'hop_giao_viec') then raise exception 'FAIL kế toán tài khoản riêng'; end if;
  if not exists(select 1 from jsonb_array_elements(public.app__viec_people()) x where (x->>'id')::bigint=kt) then raise exception 'FAIL danh sách kế toán'; end if;
  cases:=array_append(cases,'Tài khoản kế toán không gắn nhân viên');
  insert into public.account_perms(account_id,perm) values(nv,'ke_toan');
  if not public.app__cv_can_as(nv,'ke_toan') then raise exception 'FAIL quyền kế toán cộng thêm'; end if;
  delete from public.account_perms where account_id=nv;
  if public.app__cv_can_as(nv,'ke_toan') then raise exception 'FAIL thu hồi quyền'; end if;
  cases:=array_append(cases,'Quyền kế toán cộng thêm và thu hồi');
  if public.app__cv_eligible(nv,jsonb_build_object('kind','recon')) or public.app__cv_eligible(nv,jsonb_build_object('kind','commitment')) then raise exception 'FAIL dùng nhầm quyền người giao'; end if;
  cases:=array_append(cases,'Quyền được kiểm theo người nhận, không theo Chủ đang giao');

  p:=jsonb_build_object('content','Công việc kiểm thử','assignee_id',kt,'reviewer_id',owner_id,'priority','binh_thuong','due_date',to_char(public.vn_now(),'YYYY-MM-DD'));
  tid:=public.app_cv_task_save(null,p);
  perform set_config('request.jwt.claim.sub',kt_uid::text,true);
  perform public.app_viec_start(tid);
  blocked:=false; begin perform public.app_viec_submit(tid,''); exception when others then blocked:=position('Ghi kết quả' in sqlerrm)>0; end;
  if not blocked then raise exception 'FAIL thiếu kết quả'; end if;
  perform public.app_viec_submit(tid,'Đã hoàn thành kết quả thử');
  if (select status from public.tasks where id=tid)<>'cho_duyet' then raise exception 'FAIL chờ xác nhận'; end if;
  blocked:=false; begin perform public.app_cv_review(tid,true,null); exception when others then blocked:=true; end;
  if not blocked then raise exception 'FAIL kế toán tự xác nhận'; end if;
  perform set_config('request.jwt.claim.sub',owner_uid::text,true);
  perform public.app_cv_review(tid,false,'Bổ sung minh chứng');
  if (select status from public.tasks where id=tid)<>'dang_xu_ly' then raise exception 'FAIL yêu cầu làm lại'; end if;
  perform set_config('request.jwt.claim.sub',kt_uid::text,true); perform public.app_viec_submit(tid,'Đã bổ sung');
  perform set_config('request.jwt.claim.sub',owner_uid::text,true); perform public.app_cv_review(tid,true,null);
  if (select done_at from public.tasks where id=tid) is null then raise exception 'FAIL xác nhận hoàn thành'; end if;
  cases:=array_append(cases,'Báo kết quả / chờ xác nhận / làm lại / xác nhận đúng người');

  insert into public.docs(kind,title,published_title,published_version,published_at,published_html) values('quy_trinh','Quy trình kiểm thử','Quy trình kiểm thử',1,public.vn_now_text(),'<p>Kiểm thử</p>') returning id into doc;
  select x into s from jsonb_array_elements(public.app__cv_sources()) x where x->>'key'='doc_read:'||doc||':v1:e'||emp;
  if s is null or (s->>'done')::boolean then raise exception 'FAIL nghĩa vụ đọc'; end if;
  blocked:=false; begin perform public.app_cv_task_save(null,jsonb_build_object('source_key',s->>'key','assignee_id',kt,'priority','binh_thuong')); exception when others then blocked:=position('thiếu quyền' in sqlerrm)>0; end;
  if not blocked then raise exception 'FAIL giao đọc thay'; end if;
  source_task:=public.app_cv_task_save(null,jsonb_build_object('source_key',s->>'key','assignee_id',nv,'priority','binh_thuong'));
  blocked:=false; begin perform public.app_cv_task_save(null,jsonb_build_object('source_key',s->>'key','assignee_id',nv,'priority','binh_thuong')); exception when others then blocked:=position('đã có công việc' in sqlerrm)>0; end;
  if not blocked then raise exception 'FAIL trùng công việc'; end if;
  blocked:=false; begin insert into public.tasks(content,cv_key) values('Trùng kiểm thử',s->>'key'); exception when unique_violation then blocked:=true; end;
  if not blocked then raise exception 'FAIL UNIQUE'; end if;
  cases:=array_append(cases,'Đọc đúng người và khóa duy nhất chống trùng');
  perform set_config('request.jwt.claim.sub',nv_uid::text,true);
  blocked:=false; begin perform public.app_viec_submit(source_task,'Xong'); exception when others then blocked:=position('tự hoàn thành' in sqlerrm)>0; end;
  if not blocked then raise exception 'FAIL báo xong nguồn thủ công'; end if;
  perform public.app_tl_read(doc); perform public.app__cv_sync();
  if (select status from public.tasks where id=source_task)<>'hoan_thanh' then raise exception 'FAIL nguồn xong'; end if;
  delete from public.doc_reads where doc_id=doc and employee_id=emp; perform public.app__cv_sync();
  if (select status from public.tasks where id=source_task)='hoan_thanh' then raise exception 'FAIL nguồn mở lại'; end if;
  update public.docs set published_version=2 where id=doc; perform public.app__cv_sync();
  if (select status from public.tasks where id=source_task)<>'hoan_thanh' then raise exception 'FAIL phiên bản cũ'; end if;
  cases:=array_append(cases,'Nguồn hoàn thành, mở lại, phiên bản mới; không báo xong thay nguồn');

  perform set_config('request.jwt.claim.sub',owner_uid::text,true);
  p:=jsonb_build_object('kind','recurring','title','Việc lịch kiểm thử','assign_mode','account','assignee_id',kt,'priority','binh_thuong',
    'effective_date',to_char(public.vn_now()::date-2,'YYYY-MM-DD'),'frequency','daily','run_time','00:00','due_days',1,'due_time','17:00','enabled',true);
  blocked:=false; begin perform public.app_cv_rule_save(null,p,null); exception when others then blocked:=position('xem trước' in sqlerrm)>0; end;
  if not blocked then raise exception 'FAIL bật thiếu xem trước'; end if;
  preview:=public.app_cv_preview(null,p);
  if (preview->>'total')::int<>3 then raise exception 'FAIL lịch bù 3 ngày'; end if;
  rid:=public.app_cv_rule_save(null,p,preview->>'token');
  perform public.app__cv_sync(); perform public.app__cv_sync();
  if (select count(*) from public.tasks where cv_rule_id=rid)<>3 then raise exception 'FAIL lịch chạy lại trùng'; end if;
  cases:=array_append(cases,'Xem trước bắt buộc, lịch bù và chạy lại không trùng');
  p:=p||jsonb_build_object('enabled',false); perform public.app_cv_rule_save(rid,p,null);
  if (select count(*) from public.tasks where cv_rule_id=rid)<>3 then raise exception 'FAIL tắt xóa việc cũ'; end if;
  cases:=array_append(cases,'Tắt quy tắc giữ việc đã tạo');
  p:=p||jsonb_build_object('effective_date',to_char(date_trunc('month',public.vn_now())::date-interval '2 months','YYYY-MM-DD'),'frequency','monthly','monthday',31);
  out:=public.app__cv_rule_sources(0,p);
  if exists(select 1 from jsonb_array_elements(out) x where left(x->>'at',10)::date<>(date_trunc('month',left(x->>'at',10)::date)+interval '1 month -1 day')::date) then raise exception 'FAIL ngày 31 tháng ngắn'; end if;
  cases:=array_append(cases,'Lịch tháng dùng ngày cuối tháng nếu thiếu ngày 31');
  select id into br from public.branches where status='Đang hoạt động' order by id limit 1;
  insert into public.role_permissions(role,perm,allowed) values('ql','doi_soat',1) on conflict(role,perm) do update set allowed=1;
  insert into public.accounts(login_name,display_name,system_role) values('cv93q1_'||substr(gen_random_uuid()::text,1,8),'Quản lý thử A','ql') returning id into q1;
  insert into public.accounts(login_name,display_name,system_role) values('cv93q2_'||substr(gen_random_uuid()::text,1,8),'Quản lý thử B','ql') returning id into q2;
  delete from public.fin_branch_managers where branch_id=br;
  insert into public.fin_branch_managers(branch_id,account_id) values(br,q1);
  s:=jsonb_build_object('kind','recon','branch_id',br);
  if public.app__cv_pick('{"assign_mode":"branch_manager"}',s) is distinct from q1 then raise exception 'FAIL quản lý phụ trách cơ sở'; end if;
  insert into public.fin_branch_managers(branch_id,account_id) values(br,q2);
  if public.app__cv_pick('{"assign_mode":"branch_manager"}',s) is not null then raise exception 'FAIL giao tùy ý nhiều quản lý'; end if;
  if public.app__cv_pick(jsonb_build_object('assign_mode','branch_manager','backup_id',owner_id),s) is distinct from owner_id then raise exception 'FAIL dự phòng khi không rõ người chính'; end if;
  cases:=array_append(cases,'Phạm vi quản lý cơ sở; nhiều người thì chờ hoặc dự phòng');

  insert into public.shift_reports(branch_id,work_date,shift,status,completed_at) values(br,'2099-12-31','Sáng','hoan_thanh',public.vn_now_text()) returning id into sr;
  tid:=public.app_cv_task_save(null,jsonb_build_object('source_key','recon:'||sr,'assignee_id',owner_id,'priority','gap'));
  update public.shift_reports set recon_status='hoan_thanh' where id=sr; perform public.app__cv_sync();
  if (select status from public.tasks where id=tid)<>'hoan_thanh' then raise exception 'FAIL đối soát đã xong'; end if;
  update public.shift_reports set recon_status='mo_lai' where id=sr; perform public.app__cv_sync();
  if (select status from public.tasks where id=tid)='hoan_thanh' then raise exception 'FAIL đối soát mở lại'; end if;
  cases:=array_append(cases,'Đối soát dùng trạng thái hiện tại, hoàn thành/mở lại theo phiếu');

  insert into public.delivery_invoices(branch_id,work_date,state,received_at,received_date) values(br,to_char(public.vn_now(),'YYYY-MM-DD'),'da_nhan',public.vn_now_text(),public.app__nh_today()) returning id into inv;
  rt:=public.app_cv_task_save(null,jsonb_build_object('source_key','goods_recon:'||inv,'assignee_id',owner_id,'priority','binh_thuong'));
  bt:=public.app_cv_task_save(null,jsonb_build_object('source_key','goods_bill:'||inv,'assignee_id',kt,'priority','binh_thuong'));
  if coalesce((select source_state->>'blocked' from public.tasks where id=rt),'')='' then raise exception 'FAIL hàng chờ hóa đơn'; end if;
  update public.delivery_invoices set bu_path='kiem-thu-tu-hoan-tac/hoa-don.jpg' where id=inv; perform public.app__cv_sync();
  if (select status from public.tasks where id=bt)<>'hoan_thanh' or nullif((select source_state->>'blocked' from public.tasks where id=rt),'') is not null then raise exception 'FAIL đủ hóa đơn đánh thức đối soát'; end if;
  update public.delivery_invoices set recon_at=public.vn_now_text() where id=inv; perform public.app__cv_sync();
  if (select status from public.tasks where id=rt)<>'hoan_thanh' then raise exception 'FAIL đối soát hàng xong'; end if;
  update public.delivery_invoices set recon_at=null where id=inv; perform public.app__cv_sync();
  if (select status from public.tasks where id=rt)='hoan_thanh' then raise exception 'FAIL đối soát hàng mở lại'; end if;
  cases:=array_append(cases,'Hàng chờ hóa đơn, kế toán bổ sung, đối soát xong và mở lại');

  tid:=public.app_cv_task_save(null,jsonb_build_object('source_key','commitment:'||emp,'assignee_id',owner_id,'priority','binh_thuong'));
  perform public.app_tl_set_commit(emp,'da_ky_chua_nop',null); perform public.app__cv_sync();
  if (select status from public.tasks where id=tid)='hoan_thanh' then raise exception 'FAIL cam kết mới ký chưa nộp'; end if;
  perform public.app_tl_set_commit(emp,'da_ky_nop',null); perform public.app__cv_sync();
  if (select status from public.tasks where id=tid)<>'hoan_thanh' then raise exception 'FAIL cam kết đã nộp'; end if;
  cases:=array_append(cases,'Cam kết chỉ hoàn thành khi ký và nộp đủ');
  out:=public.app_cv_progress('doc_followup:'||doc||':v2');
  if not exists(select 1 from jsonb_array_elements(out) x where x->>'employee' like 'CV93_%' and not (x->>'read')::boolean) then raise exception 'FAIL tiến độ phiên bản'; end if;
  cases:=array_append(cases,'Người đôn đốc xem tiến độ nhân viên theo đúng phiên bản');

  insert into public.trainings(employee_id,program_id,branch_id,start_date) select emp,id,br,to_char(public.vn_now(),'YYYY-MM-DD') from public.training_programs order by id limit 1 returning id into tr;
  tid:=public.app_cv_task_save(null,jsonb_build_object('source_key','training:'||tr,'assignee_id',owner_id,'priority','binh_thuong'));
  update public.trainings set cont_result='dat' where id=tr; perform public.app__cv_sync();
  if (select status from public.tasks where id=tid)<>'hoan_thanh' then raise exception 'FAIL đào tạo đạt'; end if;
  cases:=array_append(cases,'Đào tạo lấy kết quả thật từ phiếu');

  tid:=public.app_cv_task_save(null,jsonb_build_object('content','Kiểm tra dự phòng','assignee_id',kt,'backup_id',owner_id,'priority','gap'));
  update public.accounts set locked=1 where id=kt; perform public.app__cv_sync();
  if (select assignee_id from public.tasks where id=tid) is distinct from owner_id then raise exception 'FAIL dự phòng'; end if;
  if public.app__cv_can_as(kt,'nhan_viec') then raise exception 'FAIL khóa tài khoản'; end if;
  cases:=array_append(cases,'Người khóa chuyển dự phòng và giữ lịch sử');
  perform public.app_cv_cancel(tid,'Hủy kiểm thử');
  blocked:=false; begin perform public.app_viec_start(tid); exception when others then blocked:=true; end;
  if not blocked then raise exception 'FAIL nhận việc hủy'; end if;
  cases:=array_append(cases,'Không nhận hoặc báo xong việc đã hủy');
  perform public.app_cv_restore(tid,'Khôi phục kiểm thử');
  if (select cancelled_at from public.tasks where id=tid) is not null then raise exception 'FAIL khôi phục'; end if;
  cases:=array_append(cases,'Khôi phục việc hủy, giữ nguyên định danh và lịch sử');
  out:=jsonb_build_array(jsonb_build_object('id',tid,'updated_at','stale'));
  blocked:=false; begin perform public.app_cv_transfer(out,nv,'Chuyển kiểm thử'); exception when others then blocked:=position('đã thay đổi' in sqlerrm)>0; end;
  if not blocked then raise exception 'FAIL chuyển từ danh sách cũ'; end if;
  cases:=array_append(cases,'Chuyển việc kiểm phiên bản xem trước, không ghi đè việc vừa đổi');
  out:=jsonb_build_array(jsonb_build_object('id',tid,'updated_at',(select updated_at from public.tasks where id=tid),'cv_revision',-1));
  blocked:=false; begin perform public.app_cv_transfer(out,nv,'Chuyển kiểm thử'); exception when others then blocked:=position('đã thay đổi' in sqlerrm)>0; end;
  if not blocked then raise exception 'FAIL chuyển cùng giây dùng bản cũ'; end if;
  cases:=array_append(cases,'Phiên bản số chặn ghi đè cả khi hai thay đổi trong cùng một giây');
  if has_function_privilege('authenticated','public.app__cv_sync()','execute') or has_table_privilege('authenticated','public.task_rules','select') then raise exception 'FAIL quyền trực tiếp'; end if;
  cases:=array_append(cases,'RPC nội bộ và bảng mới không được gọi trực tiếp');
  t0:=clock_timestamp();out:=public.app_cv_board();
  if jsonb_typeof(out->'tasks')<>'array' or jsonb_typeof(out->'sources')<>'array' or jsonb_typeof(out->'people')<>'array' then raise exception 'FAIL dữ liệu bảng'; end if;
  perform public.app_home_todo(); perform public.app_viec_reminder();
  cases:=array_append(cases,'Trung tâm, trang chủ, nhắc việc dùng trạng thái mới');
  perform public.app__cv_tick(); select count(*) into before_ from public.notifications;
  perform public.app__cv_tick();
  if (select count(*) from public.notifications)<>before_ then raise exception 'FAIL nhắc trùng trong ngày'; end if;
  cases:=array_append(cases,'Cron chạy lặp không gửi nhắc trùng trong ngày');
  raise exception 'REPORT>> %', jsonb_build_object('passed',array_length(cases,1),'cases',cases,'board_ms',round(extract(epoch from clock_timestamp()-t0)*1000),'rollback',true);
end $checks$;
